const all=['/',...hubs.map(p=>p.path),...aboutPages.map(p=>p.path),...pages.map(p=>p.path),...cases.map(p=>p.path)];
const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n${all.map(p=>{const item=[...hubs,...aboutPages,...pages,...cases].find(x=>x.path===p);const alternate=item?.alternate?`<xhtml:link rel="alternate" hreflang="${item.lang==='en'?'zh-Hant-HK':'en'}" href="${canonical(item.alternate)}"/>`:'';return `  <url><loc>${canonical(p)}</loc><lastmod>${updated}</lastmod>${alternate}</url>`}).join('\n')}\n</urlset>\n`;
fs.writeFileSync(path.join(dist,'sitemap.xml'),sitemap);
